function renderHome(){if(view!=='home')return;$('#create-page').hidden=homePage!=='create';$('#assets-page').hidden=homePage!=='assets';$('#history-page').hidden=homePage!=='history';$('#session-list').innerHTML=(workspace.sessions||[]).length?(workspace.sessions||[]).slice().reverse().map(x=>`<div class="session-card"><div class="row spread"><strong>${E(x.model)}</strong><small>${E(new Date(x.created).toLocaleString('id-ID'))} · ${x.status==='completed'?'Selesai':x.status==='failed'?'Gagal':'Memproses'}</small></div><p>${E(x.prompt)}</p><button class="mini-button" data-action="reuse-session" data-id="${E(x.id)}">Gunakan Prompt</button></div>`).join(''):'<div class="plain-empty"><span>◷</span><p>Belum ada riwayat generasi.</p></div>';$('#explore-page').hidden=homePage!=='explore';$('#elements-page').hidden=homePage!=='elements';$('#canvas-launch').hidden=homeTab!=='canvas';$('#generate-mount').hidden=homeTab!=='generate';$('#home-heading').innerHTML=homeTab==='canvas'?'Ruang Untuk <em class="hero-wordmark">Cerita</em> Yang Kamu Ciptakan.':'Wujudkan <em class="hero-wordmark">Imajinasimu</em> Tanpa Batas.';document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===homePage));document.querySelectorAll('[data-home-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.homeTab===homeTab);b.setAttribute('aria-selected',String(b.dataset.homeTab===homeTab))});document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-selected',String(b.dataset.category===category))});$('#inspiration-message').textContent=category==='Showroom'?'Ruang untuk karya dan ide baru.':`Belum ada inspirasi ${category}.`;document.querySelectorAll('[data-asset-tab]').forEach(b=>b.classList.toggle('active',b.dataset.assetTab===assetTab));document.querySelectorAll('[data-asset-kind]').forEach(b=>b.classList.toggle('active',b.dataset.assetKind===assetKind));document.querySelectorAll('[data-element-role]').forEach(b=>b.classList.toggle('active',b.dataset.elementRole===elementRole));const origin=$('#asset-origin').value,date=$('#asset-date').value,sort=$('#asset-sort').value,cutoff=date==='today'?new Date().setHours(0,0,0,0):date==='week'?Date.now()-7*86400000:0;let assets=workspace.assets.filter(a=>(assetKind==='image'?a.type.startsWith('image/'):assetKind==='video'?a.type==='video/mp4':assetKind==='audio'?a.type.startsWith('audio/'):false)&&(origin==='all'||(origin==='generated'?a.origin==='generated':a.origin!=='generated'))&&(!cutoff||Date.parse(a.created||'')>=cutoff));assets.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):((Date.parse(a.created)||0)-(Date.parse(b.created)||0))*(sort==='oldest'?1:-1));const empty=message=>`<div class="plain-empty"><span>◇</span><p>${message}</p><small>Unggahan dan hasil generasimu akan tampil di sini.</small></div>`;$('#home-asset-grid').classList.toggle('list-layout',listLayout);$('#home-asset-grid').innerHTML=assetTab==='canvases'?(renderProjectList()||empty('Belum ada canvas tersimpan.')):assets.length?groupedAssets(assets):empty('Belum ada aset di bagian ini.');if(assetTab==='generations'){const processing=workspace.projects.flatMap(p=>p.nodes).filter(n=>n.status==='processing'&&n.jobId&&n.type===assetKind);if(processing.length)$('#home-asset-grid').innerHTML+=`<section class="date-group"><h2>Sedang Diproses</h2><div class="date-media">${processing.map(n=>`<div class="render-skeleton" role="status"><span>${E(n.name)} · Memproses…</span></div>`).join('')}</div></section>`;}const elements=workspace.assets.filter(a=>a.type.startsWith('image/')&&(elementRole==='all'||(a.role||'style')===elementRole));$('#home-elements').innerHTML=elements.length?elements.map(a=>`<div class="home-asset-card">${assetPreview(a)}<span class="asset-caption">${E(a.name)}</span><select class="role-picker" data-asset-role="${E(a.id)}" aria-label="Peran ${E(a.name)}">${[['character','Karakter'],['location','Lokasi'],['property','Properti'],['style','Gaya']].map(([v,t])=>`<option value="${v}" ${v===(a.role||'style')?'selected':''}>${t}</option>`).join('')}</select></div>`).join(''):empty('Belum ada elemen referensi.');}
function goHome(page='create'){cancelLink();selection.clear();inspector=false;assetDrawerOpen=false;homePage=page;viewChange('home');if(innerWidth<=760)setSidebarCollapsed(true)}
function modeChange(mode){generateMode=mode;if(mode==='video')current().model='seedance';if(mode==='image'&&!['seedream','seedream-edit'].includes(current().model))current().model='seedream';renderDock();save();syncRoute()}
function openCanvas(id){if(id)workspace.activeId=id;selection.clear();history=new History();cancelLink();dockOpen=false;assetDrawerOpen=false;inspector=false;generateMode=current().model==='seedance'?'video':'image';viewChange('canvas');if(!current().view.initialized){fit();current().view.initialized=true}save()}
function launchCanvas(){const p=current();if(!p.nodes.length&&!p.prompt&&['Kanvas Baru','Canvas Baru'].includes(p.name))return openCanvas(p.id);if(workspace.projects.length>=30)return notify('Maksimal 30 canvas.');const next=emptyProject('Kanvas Baru');next.model='seedance';next.duration=5;next.resolution='720p';workspace.projects.push(next);openCanvas(next.id)}
function draftNode(type){if(current().nodes.length>=120)return notify('Kanvas maksimal 120 objek.');checkpoint();const v=current().view,box=$('#stage').getBoundingClientRect(),n={id:uid(),name:type==='video'?'Video Baru':'Gambar Baru',type,x:(box.width/2-v.x)/v.z-180,y:(box.height/2-v.y)/v.z-105,w:360,h:203,role:'style',status:'pending',draft:true};current().nodes.push(n);selection=new Set([n.id]);dockOpen=true;modeChange(type);render();save()}
function formatDialog(){const p=current();dialog('Format Karya',`<div class="dialog-stack"><label class="form-field">Rasio</label><div class="format-options">${['16:9','9:16','1:1','4:3','3:4'].map(r=>`<button data-action="set-ratio" data-value="${r}" class="${r===p.ratio?'active':''}">${r}</button>`).join('')}</div>${generateMode==='video'?`<label class="form-field">Resolusi</label><div class="format-options">${['480p','720p','1080p'].map(r=>`<button data-action="set-resolution" data-value="${r}" class="${r===(p.resolution||'720p')?'active':''}">${r.toUpperCase()}</button>`).join('')}</div>`:'<p class="muted small">Gambar dibuat dalam ukuran 2K sesuai rasio.</p>'}<button class="upload-button" data-action="close-modal">Selesai</button></div>`)}
function mentionElements(target='prompt'){mentionTarget=target;const images=workspace.assets.filter(a=>a.type.startsWith('image/'));dialog('Elemen · Referensi',`<div class="dialog-stack"><p class="muted small">Tambahkan karakter, lokasi, properti, atau gaya sebagai referensi prompt.</p>${images.length?images.map(a=>`<div class="element-dialog-row"><img src="${E(a.src)}" alt="${E(a.name)}"><span>${E(a.name)}</span><button class="mini-button" data-action="mention-pick" data-id="${E(a.id)}">Tambahkan</button></div>`).join(''):'<p class="muted">Belum ada elemen. Upload gambar referensi terlebih dahulu.</p>'}<button class="mini-button" data-action="upload">＋ Upload Referensi</button></div>`)}
function assetDetail(id){const a=asset(id);if(!a)return;dialog(a.name,`<div class="dialog-stack">${a.type==='video/mp4'?`<video controls src="${E(a.src)}" style="width:100%"></video>`:a.type.startsWith('audio/')?`<audio controls src="${E(a.src)}"></audio>`:`<img src="${E(a.src)}" alt="${E(a.name)}">`}<button class="upload-button" data-action="asset-to-canvas" data-id="${E(a.id)}">Tambahkan Ke Kanvas</button><button class="mini-button" data-action="download-asset" data-id="${E(a.id)}">Unduh Aset</button></div>`)}
function groupedAssets(assets){const groups=new Map();for(const a of assets){const date=a.created&&Number.isFinite(Date.parse(a.created))?new Date(a.created).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):'Tanpa Tanggal';if(!groups.has(date))groups.set(date,[]);groups.get(date).push(a)}return [...groups].map(([date,rows])=>`<section class="date-group"><h2>${E(date)}</h2><div class="date-media">${rows.map(a=>`<button class="home-asset-card" data-action="asset-detail" data-id="${E(a.id)}">${assetPreview(a)}<span class="asset-caption">${E(a.name)}</span><small>${a.origin==='generated'?'Hasil Generasi':'Unggahan'}</small></button>`).join('')}</div></section>`).join('')}
function syncRoute(replace=false){if(!globalThis.location||!globalThis.history?.pushState)return;const url=routeURL({view,page:homePage,tab:homeTab,document:current().id,mode:generateMode,assetTab,assetKind});if(location.pathname+location.search!==url)globalThis.history[replace?'replaceState':'pushState']({},'',url)}
function applyRoute(){if(!globalThis.location)return;const r=parseRoute(location.href);view=r.view;homePage=r.page;homeTab=r.tab;if(r.document){if(workspace.projects.some(p=>p.id===r.document))workspace.activeId=r.document;else{view='home';homeTab='canvas';notify('Kanvas pada tautan ini belum tersedia di perangkat ini.')}}generateMode=r.mode|| (current().model==='seedance'?'video':'image');if(view==='home'&&homeTab==='generate'&&['image','video'].includes(generateMode)){if(generateMode==='video')current().model='seedance';else if(!['seedream','seedream-edit'].includes(current().model))current().model='seedream';}if(r.assetTab)assetTab=r.assetTab;if(r.assetKind)assetKind=r.assetKind;selection.clear();dockOpen=false;assetDrawerOpen=false;}
function searchDialog(){dialog('Cari Workspace','<div class="dialog-stack"><input id="global-search-input" placeholder="Cari canvas atau aset…" aria-label="Cari canvas atau aset"><div id="global-search-results"></div></div>');const input=$('#global-search-input');input.oninput=()=>{const q=input.value.trim().toLowerCase();$('#global-search-results').innerHTML=q?workspace.projects.filter(p=>p.name.toLowerCase().includes(q)).map(p=>`<button class="project-option" data-action="search-canvas" data-id="${E(p.id)}">▧ ${E(p.name)}</button>`).join('')+workspace.assets.filter(a=>a.name.toLowerCase().includes(q)).map(a=>`<button class="project-option" data-action="asset-detail" data-id="${E(a.id)}">◇ ${E(a.name)}</button>`).join(''):'';if(q&&!$('#global-search-results').textContent)$('#global-search-results').textContent='Tidak ada hasil.'};}
function historyDialog(){dialog('History · Versi Sesi',`<div class="dialog-stack"><p class="muted small">${history.past.length} langkah dapat diurungkan · ${history.future.length} langkah dapat diulang. Riwayat versi berlaku untuk sesi editor ini.</p>${history.past.map((snapshot,i)=>`<button class="project-option" data-action="history-restore" data-index="${i}">Versi ${i+1} · ${snapshot.find(p=>p.id===workspace.activeId)?.nodes.length||0} objek</button>`).reverse().join('')}<button class="mini-button" data-action="undo">Undo</button><button class="mini-button" data-action="redo">Redo</button></div>`)}
function restoreHistory(index){if(workspace.projects.some(p=>p.nodes.some(n=>n.status==='processing')))return notify('Tunggu generasi selesai sebelum memulihkan versi.');const snapshot=history.past[index];if(!snapshot)return;const value=clone(snapshot);history.future.push(clone(workspace.projects));history.past=history.past.slice(0,index);workspace.projects=value;selection.clear();close();render();save()}
function createTemplate(kind){if(workspace.projects.length>=30)return notify('Maksimal 30 canvas.');const p=emptyProject(kind==='video'?'Video Playground':'Image Showcase');p.model=kind==='video'?'seedance':'seedream';const image={id:uid(),name:'Gambar Sumber',type:'image',x:130,y:180,w:320,h:180,role:'style',status:'pending',draft:true},note={id:uid(),name:'Arahan Kreatif',type:'note',text:'',x:130,y:440,w:320,h:120,role:'style'};p.nodes=[image,note];const target=kind==='video'?{id:uid(),name:'Video Tujuan',type:'video',x:650,y:180,w:360,h:203,role:'style',status:'pending',draft:true}:image;if(kind==='video'){p.nodes.push(target);p.links.push({id:uid(),from:image.id,to:target.id,kind:'primary',label:'Gambar → Video'})}p.links.push({id:uid(),from:note.id,to:target.id,kind:'influence',label:'Prompt'});workspace.projects.push(p);openCanvas(p.id)}
function commandCanvas(){let text=$('#canvas-command').value.trim();if(!text)return notify('Tuliskan ide atau naskah terlebih dahulu.');for(const [key,body] of Object.entries(templateText))if(text==='/'+key)text=body;if(workspace.projects.length>=30)return notify('Maksimal 30 canvas.');const refs=[...current().refs],p=emptyProject(text.split('\n')[0].slice(0,60));p.brief=text;p.prompt=text;p.refs=refs;p.model='seedance';p.duration=5;p.resolution='720p';p.nodes=[{id:uid(),type:'note',name:'Ide & Naskah',text,x:200,y:200,w:420,h:230,role:'style'}];workspace.projects.push(p);$('#canvas-command').value='';openCanvas(p.id)}
function dialog(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal').showModal()}
function close(){if($('#modal').open)$('#modal').close()}
function viewChange(value){stopPlayback();view=value;render();syncRoute()}
function fit(){const box=$('#stage').getBoundingClientRect();current().view=fitView(current().nodes,box.width||1100,box.height||760);paintViewport();save()}
function zoom(mult,point){const box=$('#stage').getBoundingClientRect();current().view=zoomAt(current().view,current().view.z*mult,point||{x:box.width/2,y:box.height/2});paintViewport();save()}
function addAsset(id,position){const a=asset(id);if(!a)return;if(current().nodes.length>=120)return notify('Satu canvas maksimal 120 objek.');checkpoint();const box=$('#stage').getBoundingClientRect(),v=current().view,at=position||{x:(box.width/2-v.x)/v.z-180,y:(box.height/2-90-v.y)/v.z-100};const n={id:uid(),type:a.type==='video/mp4'?'video':a.type.startsWith('audio/')?'audio':'image',name:a.name,assetId:id,x:at.x,y:at.y,w:360,h:a.type.startsWith('audio/')?95:203,role:a.role||'style'};current().nodes.push(n);selection=new Set([n.id]);render();save()}
function addReference(id){if(!asset(id)?.type.startsWith('image/'))return notify('Referensi generasi memakai gambar.');if(current().refs.includes(id))return notify('Ditambahkan sebagai referensi.');if(current().refs.length>=8)return notify('Maksimal delapan referensi.');checkpoint();current().refs.push(id);renderDock();renderSidebar();save();notify('Referensi ditambahkan.')} 
function duplicate(){if(!selection.size)return notify('Pilih objek terlebih dahulu.');if(current().nodes.length+selection.size>120)return notify('Kanvas sudah mencapai batas objek.');checkpoint();const copy=selected().map(n=>({...clone(n),id:uid(),x:n.x+28,y:n.y+28,name:n.name+' — Salinan'}));current().nodes.push(...copy);selection=new Set(copy.map(n=>n.id));render();save()}
function remove(){if(!selection.size)return;checkpoint();current().links=current().links.filter(l=>!selection.has(l.from)&&!selection.has(l.to));current().nodes=current().nodes.filter(n=>!selection.has(n.id));cancelLink();selection.clear();render();save()}
function arrangeSelection(mode){const targets=selection.size?selected().filter(n=>n.type!=='section'):current().nodes.filter(n=>n.type!=='section');if(!targets.length)return;checkpoint();const arranged=arrange(targets,mode),map=new Map(arranged.map(n=>[n.id,n]));current().nodes=current().nodes.map(n=>map.get(n.id)||n);close();renderCanvas();fit();save()}
function addNote(section=false){checkpoint();const v=current().view,box=$('#stage').getBoundingClientRect(),n={id:uid(),type:section?'section':'note',name:section?'Bagian Baru':'Catatan Kreatif',x:(box.width/2-v.x)/v.z-160,y:(box.height/2-100-v.y)/v.z-80,w:section?600:320,h:section?360:150,text:section?'':'Tulis arah kreatif, ide cerita, atau detail yang ingin kamu pertahankan.',role:'style'};if(current().nodes.length>=120)return notify('Kanvas sudah mencapai batas objek.');current().nodes.push(n);selection=new Set([n.id]);inspector=true;render();save()}
function referenceDialog(){dialog('Referensi Visual',`<p class="muted small">Pilih karakter, lokasi, properti, atau gaya visual dari pustaka.</p><div class="modal-grid">${workspace.assets.filter(a=>a.type.startsWith('image/')).map(a=>`<button class="${current().refs.includes(a.id)?'active':''}" data-action="pick-reference" data-id="${E(a.id)}"><img src="${E(a.src)}" alt="${E(a.name)}">${E(a.name)}</button>`).join('')}</div><p class="muted small">${current().refs.length} / 8 referensi · Klik kembali untuk melepas.</p><button class="mini-button" data-action="upload">＋ Upload Referensi</button><button class="upload-button" data-action="close-modal">Selesai</button>`)}
function projectsDialog(){dialog('Ruang Karyamu',`<div class="dialog-stack">${workspace.projects.map(p=>`<div class="project-option-row"><button class="project-option" data-action="open-project" data-id="${E(p.id)}"><span>${E(p.name)}</span><span class="muted small">${p.nodes.length} objek ${p.id===workspace.activeId?'· Aktif':''}</span></button><button class="icon-button" data-action="canvas-menu" data-id="${E(p.id)}" title="Menu kanvas" aria-label="Pilihan kanvas ${E(p.name)}">⋯</button></div>`).join('')}<input id="new-name" maxlength="80" placeholder="Judul ruang karya baru" aria-label="Judul ruang karya baru"><div class="row"><button class="upload-button" data-action="new-project">＋ Buat Ruang</button><button class="mini-button" data-action="rename-project">Ganti Judul Aktif</button></div></div>`)}
function canvasMenuDialog(id){const p=workspace.projects.find(x=>x.id===id);if(!p)return notify('Kanvas tidak ditemukan.');dialog(`Pilihan: ${p.name}`,`<div class="dialog-stack"><p class="muted small">${p.nodes.length} objek · ${p.links?.length||0} koneksi ${p.id===workspace.activeId?'· Sedang aktif':''}</p><button class="mini-button" data-action="open-project" data-id="${E(p.id)}">Buka Kanvas</button><button class="mini-button" data-action="prompt-rename-canvas" data-id="${E(p.id)}">✎ Ganti Nama</button><button class="mini-button" data-action="duplicate-canvas" data-id="${E(p.id)}">⧉ Duplikat Kanvas</button><button class="mini-button" data-action="export-single-canvas" data-id="${E(p.id)}">↓ Unduh Cadangan JSON</button><button class="mini-button" data-action="delete-canvas" data-id="${E(p.id)}" style="color:var(--danger)">🗑 Hapus Kanvas</button></div>`)}
function renameCanvasDialog(id){const p=workspace.projects.find(x=>x.id===id);if(!p)return notify('Kanvas tidak ditemukan.');dialog('Ganti Nama Kanvas',`<div class="dialog-stack"><label class="field-label" for="rename-canvas-input">Nama Kanvas</label><input id="rename-canvas-input" maxlength="80" value="${E(p.name)}" placeholder="Nama kanvas" aria-label="Nama kanvas"><div class="row"><button class="upload-button" data-action="save-canvas-name" data-id="${E(p.id)}">Simpan</button><button class="mini-button" data-action="canvas-menu" data-id="${E(p.id)}">Kembali</button></div></div>`)}
function download(name,body,type='application/json'){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
function exportWorkspace(){download('lakon-workspace.json',JSON.stringify(workspace,null,2));close();notify('Workspace diekspor, termasuk aset dan storyboard.')} 
async function upload(files,at){for(const file of files){if(!['image/png','image/jpeg','image/webp','video/mp4','audio/mpeg','audio/wav','audio/ogg'].includes(file.type)||file.size>8*1024*1024){notify('Gunakan PNG, JPG, WebP, MP4, MP3, WAV, atau OGG, maksimal 8 MB per berkas.');continue}if(workspace.assets.length>=100){notify('Pustaka maksimal 100 aset.');break}const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});try{if(file.type.startsWith('image/'))await new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=src})}catch{notify('Gambar tidak dapat dibaca.');continue}const a={id:uid(),name:file.name.slice(0,200),src,type:file.type,role:'style',origin:'upload',created:new Date().toISOString()};workspace.assets.push(a);if(view==='home'){renderHome();renderSidebar()}else addAsset(a.id,at);if(at)at={x:at.x+35,y:at.y+35}}save();$('#upload-input').value='';notify('Aset tersimpan di pustaka perangkat.')}
function stopPlayback(){clearInterval(playing);playing=null;$('#play-button').textContent='▶'}
function play(){if(playing)return stopPlayback();if(!current().timeline.length)return notify('Tambahkan frame ke storyboard terlebih dahulu.');if(storyTime>=totalDuration())storyTime=0;$('#play-button').textContent='Ⅱ';let prior=clipIndex();playing=setInterval(()=>{storyTime+=.1;if(storyTime>=totalDuration()){storyTime=0;stopPlayback()}const now=clipIndex();if(now!==prior){paintStory();prior=now}else{$('#story-time').textContent=clock(storyTime)+' / '+clock(totalDuration());$('#story-seek').value=storyTime}},100)}
async function api(path,options={}){const response=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let body;try{body=await response.json()}catch{throw Error('Backend AI belum terhubung pada halaman ini.')}if(!response.ok)throw Object.assign(Error(body.error||'Permintaan gagal.'),{code:body.code});return body}
function connection(){dialog('Koneksi Generasi AI',`<div class="dialog-stack"><div class="notice">${config.providerReady?'Konfigurasi BytePlus siap menerima permintaan.':'Editor berjalan lokal. Generasi AI memerlukan backend BytePlus yang terkonfigurasi.'}</div><p class="muted small">Konfigurasi backend: ARK_API_KEY, ARK_BASE_URL, ARK_IMAGE_MODEL, ARK_VIDEO_MODEL, dan ARK_FREE_ONLY_CONFIRMED. Secret disimpan pada server.</p><p class="muted small">Key yang sebelumnya diberikan ditolak BytePlus saat pengujian. Gunakan key ModelArk aktif dan pertahankan Free Tokens Only.</p><button class="upload-button" data-action="check-connection">Periksa Backend</button></div>`)}
function updateNodeStatus(projectId,nodeId,status,jobId){const p=workspace.projects.find(p=>p.id===projectId),n=p?.nodes.find(n=>n.id===nodeId);if(n){n.status=status;if(jobId)n.jobId=jobId;else if(status!=='ready')delete n.jobId;renderCanvas();renderDock();save()}}
function generationBlock(p,n){if(n?.status==='processing')return 'Node ini masih memproses generasi.';const blocked=dependencyBlockers(p,n?.id);if(blocked.length)return 'Menunggu dependensi solid selesai: '+blocked.map(n=>n?.name||'Sumber').join(', ');return ''}
async function generate(){if(!['image','video'].includes(generateMode)){if(generateMode==='agent'){current().brief=current().prompt;save();return notify('Arahan disimpan sebagai brief. AI Agent belum terhubung.')}return notify((generateMode==='audio'?'AI Audio':'AI Avatar')+' belum terhubung ke provider.');}const p=current(),target=(view==='home'?[]:selected()).find(n=>['image','video'].includes(n.type)),block=generationBlock(p,target);if(block)return notify(block);const context=generationContext(p,target?.id);if(!context.prompt.trim())return notify('Tuliskan prompt atau hubungkan catatan berisi arahan.');if(context.references.length>8)return notify('Gabungan referensi manual dan connector maksimal delapan gambar.');if(context.prompt.length>5700)return notify('Gabungan prompt dan catatan terlalu panjang. Maksimal 5.700 karakter agar pemetaan referensi tetap muat.');if(context.unsupported.length)return notify('Input video/audio terhubung, tetapi generasi saat ini menerima referensi gambar. Gunakan gambar sumber; klip video dapat disusun di storyboard.');if(!config.providerReady)return connection();if(p.model==='seedream-edit'&&!context.references.length)return notify('Pilih atau hubungkan setidaknya satu gambar referensi.');dialog('Kirim Arahan Ke BytePlus?',`<div class="dialog-stack"><div class="notice">${E(context.prompt)}<br><br>${E(p.model)} · ${E(p.ratio)} · ${context.references.length} referensi${target?'<br>Tujuan: '+E(target.name):''}</div><p class="muted small">Prompt dan gambar referensi dikirim ke BytePlus. Free Tokens Only harus tetap aktif di akunmu. Permintaan tidak diulang otomatis.</p><button id="confirm-generation" class="upload-button">Kirim Generasi</button></div>`);$('#confirm-generation').onclick=async e=>{const latest=workspace.projects.find(x=>x.id===p.id),node=latest?.nodes.find(n=>n.id===target?.id);if(!latest||(target&&!node)){close();return notify('Node tujuan sudah berubah. Pilih kembali sebelum generasi.')}const block=generationBlock(latest,node);if(block){close();return notify(block)}e.target.disabled=true;const projectId=p.id,nodeId=node?.id,requestId=uid();workspace.sessions??=[];workspace.sessions.push({id:requestId,projectId,nodeId:nodeId||null,prompt:context.prompt,model:p.model,created:new Date().toISOString(),status:'processing',origin:view});workspace.sessions=workspace.sessions.slice(-100);save();updateNodeStatus(projectId,nodeId,'processing');try{const references=[];for(const ref of context.references){const a=asset(ref.id);if(!a)throw Error('Aset referensi tidak ditemukan.');if(!a.remoteId){let blob;if(a.src.startsWith('data:')){const comma=a.src.indexOf(','),bin=atob(a.src.slice(comma+1));blob=new Blob([Uint8Array.from(bin,c=>c.charCodeAt(0))],{type:a.type})}else blob=await(await fetch(a.src)).blob();const response=await fetch('/api/uploads',{method:'POST',headers:{'Content-Type':a.type,'X-File-Name':encodeURIComponent(a.name)},body:blob});const result=await response.json();if(!response.ok)throw Error(result.error||'Unggah referensi gagal');a.remoteId=result.id}references.push({id:a.remoteId,role:ref.role||a.role||'style'})}const job=await api('generate',{method:'POST',body:JSON.stringify({requestID:requestId,model:p.model,prompt:context.prompt+(references.length?'\nReference mapping: '+references.map((r,i)=>'Image '+(i+1)+': '+r.role+' reference').join('; '):''),ratio:p.ratio,count:1,duration:Number(p.duration),resolution:p.resolution||'720p',references,projectID:projectId,nodeID:nodeId,primarySourceNodeIDs:latest.links.filter(l=>l.to===nodeId&&l.kind==='primary').map(l=>l.from)})});close();if(job.status==='completed')applyJob(job,projectId,nodeId);else if(job.status==='failed')throw Error(job.error||'Generasi gagal.');else{updateNodeStatus(projectId,nodeId,'processing',job.id);notify('Video sedang diproses BytePlus. Node berikutnya menunggu.');poll(job.id,projectId,nodeId)}}catch(e){const session=workspace.sessions?.find(x=>x.id===requestId);if(session)session.status='failed';save();updateNodeStatus(projectId,nodeId,e.code==='SUBMISSION_UNCERTAIN'?'pending':'failed');close();notify(e.message);if(e.code==='FREE_QUOTA_EXHAUSTED')config.providerReady=false}}}
function applyJob(job,projectId,nodeId){const session=workspace.sessions?.find(x=>x.id===job.id);if(session)session.status='completed';const p=workspace.projects.find(p=>p.id===projectId);if(!p)return;const target=p.nodes.find(n=>n.id===nodeId);if(!job.outputs?.length){if(session)session.status='failed';updateNodeStatus(projectId,nodeId,'failed');return notify('BytePlus belum memberikan output yang valid.')}checkpoint();for(const [i,output] of job.outputs.entries()){let a=asset(output.id);if(!a){a={id:output.id,name:'Hasil · '+(job.prompt||'Generasi').slice(0,55),src:output.url,type:output.type,remoteId:output.id,role:'style',origin:'generated',created:new Date().toISOString()};workspace.assets.push(a)}if(target&&i===0){target.assetId=a.id;target.type=a.type==='video/mp4'?'video':'image';target.status='ready';delete target.draft;target.jobId=job.id}else if(!nodeId&&(session?.origin||view)!=='home'&&p.nodes.length<120)p.nodes.push({id:uid(),type:a.type==='video/mp4'?'video':a.type.startsWith('audio/')?'audio':'image',name:a.name,assetId:a.id,x:100+p.nodes.length*12,y:100+p.nodes.length*10,w:420,h:236,role:'style',status:'ready'})}render();save();notify('Hasil BytePlus siap. Dependensi berikutnya dapat dijalankan.')}
async function poll(id,projectId,nodeId){if(activePolls.has(id))return;activePolls.add(id);try{for(let i=0;i<90;i++){await new Promise(r=>setTimeout(r,4000));try{const j=await api('jobs/'+id);if(j.status==='completed')return applyJob(j,projectId,nodeId);if(j.status==='failed'){const session=workspace.sessions?.find(x=>x.id===id);if(session)session.status='failed';save();updateNodeStatus(projectId,nodeId,'failed');return notify(j.error||'Generasi tidak berhasil.')}}catch(e){notify('Status generasi belum dapat diperiksa. Node tujuan tetap menunggu.');return}}notify('Video masih diproses. Gunakan Periksa Backend untuk melanjutkan pemeriksaan.')}finally{activePolls.delete(id)}}
function resumeJobs(){for(const p of workspace.projects)for(const n of p.nodes)if(n.status==='processing'&&n.jobId)poll(n.jobId,p.id,n.id)}
