$('#asset-search').addEventListener('input',e=>{search=e.target.value;renderSidebar()});$('#prompt').addEventListener('input',e=>{current().prompt=e.target.value;save()});$('#creative-brief').addEventListener('input',e=>{current().brief=e.target.value.slice(0,6000);save()});$('#task').addEventListener('change',e=>{modeChange(e.target.value)});$('#model').addEventListener('change',e=>{current().model=e.target.value;save()});$('#ratio').addEventListener('change',e=>{current().ratio=e.target.value;save()});$('#duration').addEventListener('change',e=>{current().duration=Number(e.target.value);save()});$('#story-seek').addEventListener('input',e=>{stopPlayback();storyTime=Number(e.target.value);paintStory()});$('#upload-input').addEventListener('change',e=>upload(e.target.files));$('#import-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>48*1024*1024)throw Error('Workspace maksimal 48 MB.');const value=validateWorkspace(JSON.parse(await file.text()));removeDemoPhotos(value);dialog('Ganti Workspace Pada Perangkat?',`<div class="dialog-stack"><p class="muted">Berkas ini berisi ${value.projects.length} proyek dan ${value.assets.length} aset. Ekspor draft saat ini jika ingin menyimpannya.</p><button id="confirm-import" class="upload-button">Impor Workspace</button></div>`);$('#confirm-import').onclick=()=>{cancelLink();workspace=value;selection.clear();history=new History();close();render();save();notify('Workspace berhasil diimpor.')}}catch(err){notify(err.message)}e.target.value=''});
document.addEventListener('change',e=>{if(e.target.dataset.property){const n=selected()[0];if(!n)return;const key=e.target.dataset.property;let value=e.target.value;if(['w','h'].includes(key)){value=Number(value);if(!Number.isFinite(value)||value<(key==='w'?60:40)||value>10000)return notify('Ukuran frame di luar batas.')}checkpoint();n[key]=value;renderCanvas();save()}if(e.target.dataset.duration!==undefined){const v=Number(e.target.value);if(!Number.isFinite(v)||v<1||v>30)return notify('Durasi harus 1–30 detik.');checkpoint();current().timeline[Number(e.target.dataset.duration)].duration=v;renderStory();save()}});
const stage=$('#stage');stage.addEventListener('pointerdown',e=>{if(e.target.closest('audio,video'))return;const port=e.target.closest('[data-port]'),edge=e.target.closest('[data-link]');if(edge){editLink(edge.dataset.link);return}if(port&&e.button===0){if(port.dataset.port==='out'){linkFrom=port.dataset.id;linkPoint=null;drag={kind:'connect',pos:{x:e.clientX,y:e.clientY},moved:false};port.classList.add('active');stage.setPointerCapture(e.pointerId)}return}if(e.target.closest('button'))return;const node=e.target.closest('[data-node]'),box=stage.getBoundingClientRect();const pos={x:e.clientX-box.left,y:e.clientY-box.top},p=current();if(tool==='hand'||space||e.button===1){drag={kind:'pan',pos,view:clone(p.view)};stage.setPointerCapture(e.pointerId);return}if(e.button!==0)return;const resize=e.target.dataset.resize;if(node&&tool==='connect'){if(linkFrom)createLink(node.dataset.node);else{linkFrom=node.dataset.node;renderCanvas()}return}if(node){const id=node.dataset.node;if(e.shiftKey){selection.has(id)?selection.delete(id):selection.add(id)}else if(!selection.has(id))selection=new Set([id]);drag={kind:resize?'resize':'nodes',pos,previous:clone(workspace.projects),nodes:selected().map(n=>clone(n)),id:resize,z:p.view.z};renderCanvas();renderInspector();renderDock()}else{cancelLink();selection.clear();drag={kind:'box',pos};renderCanvas();renderInspector();$('#selection-box').hidden=false}stage.setPointerCapture(e.pointerId);stage.focus()});
stage.addEventListener('pointermove',e=>{if(!drag)return;const box=stage.getBoundingClientRect(),pos={x:e.clientX-box.left,y:e.clientY-box.top},dx=pos.x-drag.pos.x,dy=pos.y-drag.pos.y,p=current();if(drag.kind==='connect'){drag.moved=drag.moved||Math.hypot(e.clientX-drag.pos.x,e.clientY-drag.pos.y)>5;linkPoint={x:(pos.x-p.view.x)/p.view.z,y:(pos.y-p.view.y)/p.view.z};paintEdges();return}if(drag.kind==='pan'){p.view.x=drag.view.x+dx;p.view.y=drag.view.y+dy;paintViewport()}else if(drag.kind==='nodes'){for(const before of drag.nodes){const n=p.nodes.find(n=>n.id===before.id);n.x=Math.max(-20000,Math.min(20000,before.x+dx/drag.z));n.y=Math.max(-20000,Math.min(20000,before.y+dy/drag.z));const el=$(`[data-node="${n.id}"]`);if(el){el.style.left=n.x+'px';el.style.top=n.y+'px'}}}else if(drag.kind==='resize'){const n=p.nodes.find(n=>n.id===drag.id),before=drag.nodes.find(n=>n.id===drag.id);if(!n||!before)return;n.w=Math.max(60,Math.min(10000,before.w+dx/drag.z));n.h=Math.max(40,Math.min(10000,before.h+dy/drag.z));const el=$(`[data-node="${n.id}"]`);el.style.width=n.w+'px';el.style.height=n.h+'px'}else{const x=Math.min(pos.x,drag.pos.x),y=Math.min(pos.y,drag.pos.y),w=Math.abs(dx),h=Math.abs(dy),el=$('#selection-box');Object.assign(el.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});selection=new Set(p.nodes.filter(n=>n.type!=='section'&&n.x*p.view.z+p.view.x<x+w&&(n.x+n.w)*p.view.z+p.view.x>x&&n.y*p.view.z+p.view.y<y+h&&(n.y+n.h)*p.view.z+p.view.y>y).map(n=>n.id))}if(['nodes','resize'].includes(drag.kind))paintEdges()});
function finishDrag(e){if(!drag)return;if(drag.kind==='connect'){const moved=drag.moved;drag=null;if(e?.type==='pointercancel'||!e){cancelLink();return}if(moved){const target=document.elementFromPoint?.(e.clientX,e.clientY),node=target?.closest('[data-node]');if(node&&node.dataset.node!==linkFrom)createLink(node.dataset.node);else cancelLink();suppressPortClick=true;setTimeout(()=>suppressPortClick=false,0)}paintEdges();return}if(['nodes','resize'].includes(drag.kind)){history.past.push(drag.previous);if(history.past.length>30)history.past.shift();history.future=[]}drag=null;$('#selection-box').hidden=true;renderCanvas();renderInspector();renderDock();save()}stage.addEventListener('pointerup',finishDrag);stage.addEventListener('pointercancel',finishDrag);stage.addEventListener('wheel',e=>{e.preventDefault();const box=stage.getBoundingClientRect();if(e.ctrlKey||e.metaKey)zoom(Math.exp(-e.deltaY*.004),{x:e.clientX-box.left,y:e.clientY-box.top});else{current().view.x-=e.deltaX;current().view.y-=e.deltaY;paintViewport();save()}},{passive:false});stage.addEventListener('dblclick',e=>{const node=e.target.closest('[data-node]');if(node){selection=new Set([node.dataset.node]);const n=selected()[0];inspector=true;if(['image','video'].includes(n?.type)){dockOpen=true;modeChange(n.type)}renderInspector();renderDock()}else dialog('Tambahkan Ke Kanvas','<div class="dialog-stack"><button class="mini-button" data-action="note">Text</button><button class="mini-button" data-action="draft-image">Image</button><button class="mini-button" data-action="draft-video">Video</button><button class="mini-button" data-action="upload">Upload From Device</button></div>')});stage.addEventListener('contextmenu',e=>{e.preventDefault();dialog('Pilihan Kanvas','<div class="dialog-stack"><button class="mini-button" data-action="upload">Unggah Gambar</button><button class="mini-button" data-action="note">Tambahkan Catatan</button><button class="mini-button" data-action="arrange-grid">Susun Dalam Grid</button><button class="mini-button" data-action="fit">Tampilkan Semua Frame</button></div>')});stage.addEventListener('dragover',e=>e.preventDefault());stage.addEventListener('drop',e=>{e.preventDefault();const box=stage.getBoundingClientRect(),v=current().view;upload(e.dataTransfer.files,{x:(e.clientX-box.left-v.x)/v.z,y:(e.clientY-box.top-v.y)/v.z})});
document.addEventListener('keydown',e=>{const typing=e.target.matches('input,textarea,select,[contenteditable]');if(typing||$('#modal').open||view!=='canvas')return;if(e.code==='Space'){e.preventDefault();space=true;paintViewport()}const key=e.key.toLowerCase(),cmd=e.metaKey||e.ctrlKey;if(cmd&&key==='a'){e.preventDefault();selection=new Set(current().nodes.filter(n=>n.type!=='section').map(n=>n.id));renderCanvas();renderInspector()}else if(cmd&&key==='d'){e.preventDefault();duplicate()}else if(cmd&&key==='z'){e.preventDefault();if(workspace.projects.some(p=>p.nodes.some(n=>n.status==='processing')))return notify('Tunggu generasi selesai sebelum undo/redo.');cancelLink();const value=e.shiftKey?history.redo(workspace.projects):history.undo(workspace.projects);if(value){workspace.projects=value;selection.clear();render();save()}}else if(cmd&&key==='o'){e.preventDefault();$('#upload-input').click()}else if(key==='delete'||key==='backspace'){e.preventDefault();remove()}else if(key==='h'||key==='v'||key==='c'){cancelLink();tool=key==='h'?'hand':key==='c'?'connect':'select';paintViewport();document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool))}else if(key==='f')fit();else if(key==='escape'){cancelLink();selection.clear();renderCanvas();renderInspector()}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)&&selection.size){e.preventDefault();checkpoint();const step=e.shiftKey?10:1;for(const n of selected()){n.x+=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;n.y+=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0}renderCanvas();save()}});document.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;paintViewport()}});window.addEventListener('blur',()=>{space=false;finishDrag();paintViewport()});
